(function(){'use strict';if(window.SVV&&SVV.iconBase&&window.L&&L.Icon&&L.Icon.Default){L.Icon.Default.mergeOptions({iconUrl:SVV.iconBase+'marker-icon.png',iconRetinaUrl:SVV.iconBase+'marker-icon-2x.png',shadowUrl:SVV.iconBase+'marker-shadow.png'});}function debounce(n,t){let e=null;return function(...o){if(e)clearTimeout(e);e=setTimeout(()=>n.apply(null,o),t);};}function computeScale(n){const t=160,e=520,o=(n-t)/(e-t);return Math.max(0.8,Math.min(1.3,o));}function initMap(el){if(el.dataset.inited)return;el.dataset.inited='1';if(typeof L==='undefined'||!L.map){console.warn('Leaflet not loaded yet, retrying...',el);setTimeout(()=>{delete el.dataset.inited;initMap(el);},500);return;}const lat=parseFloat(el.getAttribute('data-lat')),lon=parseFloat(el.getAttribute('data-lon'));if(isNaN(lat)||isNaN(lon)){console.warn('Missing or invalid lat/lon for map',el);return;}const computedHeight=window.getComputedStyle(el).height;if(!computedHeight||computedHeight==='0px'||computedHeight==='auto'){console.warn('Map element has no height, retrying...',el);setTimeout(()=>{delete el.dataset.inited;initMap(el);},500);return;}try{const map=L.map(el,{scrollWheelZoom:!1,attributionControl:!1});el._svvMap=map;map.setView([lat,lon],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(map);setTimeout(()=>map.invalidateSize(),200);}catch(n){console.error('Error initializing map:',n);delete el.dataset.inited;}}function scanMapsLazy(){const maps=Array.from(document.querySelectorAll('.svv-map'));if(!maps.length)return;if('IntersectionObserver' in window){const io=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){initMap(entry.target);io.unobserve(entry.target);}});},{root:null,rootMargin:'200px',threshold:0.01});maps.forEach(function(m){if(m.dataset.inited)return;io.observe(m);});return;}maps.forEach(initMap);}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',scanMapsLazy);}else{scanMapsLazy();}new MutationObserver(scanMapsLazy).observe(document.documentElement,{childList:!0,subtree:!0});const attachRO=debounce(function(){if(!('ResizeObserver'in window))return;document.querySelectorAll('.sv-vader[data-svv-ro="1"], .spelhubben-weather[data-svv-ro="1"]').forEach(function(card){if(card._svvObserved)return;card._svvObserved=!0;const applyScale=()=>{const w=(card.getBoundingClientRect().width||card.clientWidth||0);if(!w)return;card.style.setProperty('--svv-scale',computeScale(w).toFixed(3));if(card._svvLastW&&Math.abs(w-card._svvLastW)>2){const m=card.querySelector('.svv-map');if(m&&m._svvMap)m._svvMap.invalidateSize()}card._svvLastW=w};applyScale();const ro=new ResizeObserver(debounce(applyScale,60));ro.observe(card);card._svvResizeObserver=ro;});},50);if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',attachRO);}else{attachRO();}const mutationObserver=new MutationObserver(function(mutations){mutations.forEach(function(m){if(m.removedNodes.length){m.removedNodes.forEach(function(node){if(node.nodeType===1){const cards=node.querySelectorAll?node.querySelectorAll('.sv-vader[data-svv-ro="1"], .spelhubben-weather[data-svv-ro="1"]'):[];cards.forEach(function(card){if(card._svvResizeObserver){card._svvResizeObserver.disconnect();delete card._svvResizeObserver;}if(card._svvMap){card._svvMap.remove();delete card._svvMap;}delete card._svvObserved;});}});}});attachRO();});mutationObserver.observe(document.documentElement,{childList:!0,subtree:!0});})();